export type ParsedClaimActionInstruction<
  TProgram extends string = typeof TEQUILA_GACHA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    player: TAccountMetas[0];
    machine: TAccountMetas[1];
    playerState: TAccountMetas[2];
    pull: TAccountMetas[3];
    asset: TAccountMetas[4];
    collection: TAccountMetas[5];
    coreAuthority: TAccountMetas[6];
    mplCoreProgram: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
    sourceProgram: TAccountMetas[9];
    escrowAuth: TAccountMetas[10];
    /** came through the post-undelegate action; it pays the asset rent. */
    escrow: TAccountMetas[11];
  };
  data: ClaimActionInstructionData;
};

export function parseClaimActionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimActionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      player: getNextAccount(),
      machine: getNextAccount(),
      playerState: getNextAccount(),
      pull: getNextAccount(),
      asset: getNextAccount(),
      collection: getNextAccount(),
      coreAuthority: getNextAccount(),
      mplCoreProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      sourceProgram: getNextAccount(),
      escrowAuth: getNextAccount(),
      escrow: getNextAccount(),
    },
    data: getClaimActionInstructionDataDecoder().decode(instruction.data),
  };
}
